    },
    {
      "id": "Q2",
      "question": "Is this condition an emergency requiring immediate intervention?",
      "my_answer": "No, it requires non‑emergent care.",
      "rationale": "There is no eye pain, photophobia, purulent discharge, vision loss, or signs of corneal involvement that would mandate emergent evaluation."
    },
